        emon.Testport.AssertEq(np, 2, "two pages");
        while (i < np) {
            emon.Testport.AssertEq(RptRow(pl, i, Rasterplan.RpFAsk()), Rasterplan.RpAskFull(), "the whole render with its text");
            emon.Testport.AssertEq(RptRow(pl, i, Rasterplan.RpFWn()), 0, "no witness line");
