    [Xunit.Fact]
    public static void TestWitnessReadsTheRenderWithoutTheTextAndAFewLinesOfEveryFont() {
        emon.Port.Cells pl = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells fl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        int np = RptPlan(0, emon.Testport.TestFile("corpus/synth/pdf/h-plain.pdf"), 2, Rasterplan.RpScopeWitness(), pl, fw, fl, et);
        int i = 0;
        int j = 0;
        int at = 0;
        int l = 0;
        int same = 0;
        int q = 0;
        int cnt = 0;
        int @base = 0;
        int other = 0;
        emon.Testport.AssertEq(np, 2, "two pages");
        while (i < np) {
            cnt = RptRow(pl, i, Rasterplan.RpFWn());
            @base = RptRow(pl, i, Rasterplan.RpFWat());
            emon.Testport.AssertEq(RptRow(pl, i, Rasterplan.RpFAsk()), Rasterplan.RpAskWitness(), "witness");
            emon.Testport.AssertThat(cnt > 0, "a page of text has witness lines");
            emon.Testport.AssertThat(cnt <= Rasterplan.RpWitnessMax(), "within the page's ceiling");
            j = 0;
            while (j < cnt) {
                at = @base + (j * Rasterplan.RpWw());
                l = emon.Port.CellsAt(pl, at + 1);
                emon.Testport.AssertEq(emon.Port.CellsAt(pl, at), i, "the row's page");
                emon.Testport.AssertEq(Evidence.LnGet(fl, l, Evidence.LhPage()), i + 1, "its line is on that page");
                emon.Testport.AssertEq(Evidence.LnGet(fl, l, Evidence.LhRot()), 0, "upright");
                emon.Testport.AssertEq(Evidence.WdGet(fw, Evidence.LnGet(fl, l, Evidence.LhFirst()), Evidence.WfFont()), emon.Port.CellsAt(pl, at + 6), "of the row's font");
                // no line twice
                same = 0;
                q = 0;
                while (q < cnt) {
                    other = emon.Port.CellsAt(pl, (@base + (q * Rasterplan.RpWw())) + 1);
                    if (other == l) {
                        same += 1;
                    }
                    q += 1;
                }
                emon.Testport.AssertEq(same, 1, "a line once");
                j += 1;
            }
            i += 1;
        }
    }
    internal static int RptField(int emonT, byte[] file, int policy, int scope, int page, int f) {
        // Plan the document and answer one field of one page's row.
        emon.Port.Cells pl = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells fl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        RptPlan(emonT, file, policy, scope, pl, fw, fl, et);
        return RptRow(pl, page, f);
    }
    internal static int RptAsked(int emonT, byte[] file, int policy, int scope, int pages, int what) {
        // The pages (of the first `pages`) whose `ask` is `what`.
        int i = 0;
        int n = 0;
        while (i < pages) {
            if (RptField(emonT, file, policy, scope, i, Rasterplan.RpFAsk()) == what) {
                n += 1;
            }
            i += 1;
        }
        return n;
    }
